import React, { forwardRef, ReactNode, useMemo, useState } from 'react';
import { isElement } from 'react-is';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { ActionGroup } from './action-group/ActionGroup.js';
import { ActionButton } from './ActionButton.js';
import { ActionItems } from './ActionItems.js';
import { AppIcon } from './AppIcon.js';
import { AppNavLink } from './AppNavLink.js';
import { ActionItemsContext } from './contexts/ActionItemsContext.js';
import { NavItemsContext } from './contexts/NavItemsContext.js';
import { NavItems } from './NavItems.js';
import { OverlayStackingProvider } from '../../core/providers/OverlayStackingProvider.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

// #region Typings
export interface AppHeaderProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the AppHeader. */
  children?: ReactNode;
}

type AppHeaderSlots = {
  navigation: React.ReactNode | null;
  actions: React.ReactNode | null;
};
// #endregion

// #region Styled components
const StyledAppHeader = styled.header({
  position: 'relative',
  display: 'flex',
  gap: Spacings.Size4,
  justifyContent: 'space-between',
});
// #endregion

/** Iterates over child nodes to extract specific component slots. */
function getItemSlots(children: ReactNode) {
  const slots: AppHeaderSlots = {
    navigation: null,
    actions: null,
  };

  for (const child of React.Children.toArray(children)) {
    if (isElement(child)) {
      switch (child.type) {
        case NavItems:
          slots.navigation = child;
          break;
        case ActionItems:
          slots.actions = child;
          break;
        default:
          break;
      }
    } else {
      // eslint-disable-next-line no-console
      console.warn('The used child is not supported by the AppHeader.');
    }
  }

  return slots;
}

const _AppHeader = forwardRef<HTMLDivElement, AppHeaderProps>(
  (props, forwardedRef) => {
    const {
      children,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: AppHeaderProps = props;
    const slots = useMemo(() => getItemSlots(children), [children]);

    const [isActionItemsCollapsed, setIsActionItemsCollapsed] = useState(
      !slots.actions,
    );
    const [isNavOverflowing, setIsNavOverflowing] = useState(false);

    return (
      <StyledAppHeader
        ref={forwardedRef}
        className={consumerClassName}
        style={consumerStyle}
        {...remainingProps}
        data-testid={dataTestId}
      >
        <ActionItemsContext.Provider
          value={{
            hasActions: !!slots.actions,
            isActionItemsCollapsed,
            setIsActionItemsCollapsed,
          }}
        >
          <NavItemsContext.Provider
            value={{
              hasNavItems: !!slots.navigation,
              isNavOverflowing,
              setIsNavOverflowing,
            }}
          >
            <OverlayStackingProvider>
              {slots.navigation ?? <AppHeader.NavItems />}
              {slots.actions}
            </OverlayStackingProvider>
          </NavItemsContext.Provider>
        </ActionItemsContext.Provider>
      </StyledAppHeader>
    );
  },
);

(_AppHeader as typeof _AppHeader & { displayName: string }).displayName =
  'AppHeader';

/**
 * The AppHeader component is a responsive header with navigational and action items.
 */
export const AppHeader = Object.assign(_AppHeader, {
  AppNavLink,
  AppIcon,
  NavItems,
  NavItem: ActionGroup.NavItem,
  ActionItems,
  ActionItemGroup: ActionGroup.Group,
  ActionButton,
});
